-- Carga de las 18 plantillas DEMO (programa × nivel × sexo · variante 90), cada una con LOWER / UPPER / FULL BODY
-- de 2 bloques × 3 sets. Idempotente: salta las combinaciones ya cargadas.
create or replace function public._koach_demo_cargar(p_prog text, d jsonb)
returns int language plpgsql security definer set search_path = public as $f$
-- d = [[nivel, sexo, [[zona, [[ej,reps],..B1], [[ej,reps],..B2]], ...]], ...]
declare x jsonb; z jsonb; e jsonb; v_pid uuid; v_sid uuid; v_bid uuid; v_eid uuid; k int; o int; n int := 0; bi int;
  v_niv text; v_sx text; v_d1 int; v_d2 int; v_et2 text; v_zn text;
begin
  perform set_config('koach.sync','1',true);
  for x in select * from jsonb_array_elements(d) loop
    v_niv := x->>0; v_sx := x->>1;
    if exists (select 1 from protocolos where estado='demo' and socio_id is null and programa::text=p_prog and nivel::text=v_niv and sexo::text=v_sx) then continue; end if;
    v_d1 := case p_prog when 'STRONG' then case when v_niv='AVANZADO' then 150 else 120 end when 'BURN' then 60 else 75 end;
    v_d2 := case p_prog when 'STRONG' then 75 when 'BURN' then 45 else 60 end;
    v_et2 := case p_prog when 'BURN' then 'FINISHER' else 'COMPLEMENTO' end;
    insert into protocolos(programa, nivel, sexo, nombre, ciclo_semanas, socio_id, estado, variante, activo)
      values (p_prog::programa_tipo, v_niv::nivel_tipo, v_sx::user_sex,
              'DEMO '||p_prog||' '||upper(v_sx)||' '||case v_niv when 'BASICO' then 'BÁSICO' else v_niv end, 1, null, 'demo', 90, true)
      returning id into v_pid;
    k := 0;
    for z in select * from jsonb_array_elements(x->2) loop
      k := k + 1; v_zn := z->>0;
      insert into sesiones_protocolo(protocolo_id, numero, nombre, objetivo, semana, publicado)
        values (v_pid, k, 'DEMO '||v_zn||' BODY', v_zn, 1, true) returning id into v_sid;
      for bi in 1..2 loop
        insert into bloques(sesion_id, bloque, rol, sets, descanso_segundos, descanso_seg, etiqueta)
          values (v_sid, ('B'||bi)::bloque_tipo, (case bi when 1 then 'fuerza_principal' else 'cierre_accesorio' end)::bloque_rol, 3,
                  case bi when 1 then v_d1 else v_d2 end, case bi when 1 then v_d1 else v_d2 end, case bi when 1 then 'PRINCIPAL' else v_et2 end)
          returning id into v_bid;
        o := 0;
        for e in select * from jsonb_array_elements(z->bi) loop
          o := o + 1;
          select id into v_eid from ejercicios where nombre = e->>0 and activo limit 1;
          if v_eid is null then raise exception 'DEMO: ejercicio no está en la biblioteca: %', e->>0; end if;
          insert into bloque_ejercicios(bloque_id, ejercicio_id, orden, reps_txt, es_ancla) values (v_bid, v_eid, o, e->>1, false);
        end loop;
      end loop;
    end loop;
    n := n + 1;
  end loop;
  perform set_config('koach.sync','0',true);
  return n;
end $f$;
revoke all on function public._koach_demo_cargar(text, jsonb) from public, anon, authenticated;

